<?php

/*
    What used to be the views of the database. Some shared hosts do not allow
    CREATE VIEW, so each one is a SELECT used as a derived table:
    "SELECT * FROM " . from('Graduatoria') reads like the old view did,
    ordering included.
*/

declare(strict_types=1);

namespace IlSole\Views;

use InvalidArgumentException;

const VIEWS = [
