    'Confirmation' => "SELECT `R`.`Cod_Fiscale` AS `Cod_Fiscale`, `R`.`Cognome` AS `Cognome`, `R`.`Nome` AS `Nome`, `R`.`nMembri` AS `nMembri`, `P`.`PunteggioISEE` AS `PunteggioISEE`, `P`.`PunteggioPresenzaMinori` AS `PunteggioPresenzaMinori`, `P`.`PunteggioDisoccupazione` AS `PunteggioDisoccupazione`, `P`.`PunteggioInvalidi` AS `PunteggioInvalidi`, `P`.`PunteggioSituazioneDebitoria` AS `PunteggioSituazioneDebitoria`, `P`.`PunteggioBenefit` AS `PunteggioBenefit`, `P`.`PunteggioTotale` AS `PunteggioTotale`, `TR`.`CodiceTessera` AS `CodiceTessera`, date_format(`TR`.`DataOraRilascioTessera`,'%Y/%m/%d') AS `DataOraRilascioTessera`, date_format(`TR`.`DataOraScadenzaTessera`,'%Y/%m/%d') AS `DataOraScadenzaTessera`, date_format(`R`.`DataOraRitiroTessera`,'%Y/%m/%d') AS `DataOraRitiroTessera`, date_format(`R`.`DataOraStalloTessera`,'%Y/%m/%d') AS `DataOraStalloTessera` FROM (((`Richiedente` `R` left join `TesseraRilasciata` `TR` on(`R`.`Cod_Fiscale` = `TR`.`CodFamiglia`)) left join `Tessera` `T` on(`TR`.`CodiceTessera` = `T`.`Codice`)) join `Punteggio` `P` on(`R`.`Cod_Fiscale` = `P`.`CodFamiglia`)) ORDER BY `P`.`PunteggioTotale` DESC",
    'Export' => "SELECT `R`.`Cod_Fiscale` AS `Cod_Fiscale`, `R`.`Cognome` AS `Cognome`, `R`.`Nome` AS `Nome`, `R`.`Cittadinanza` AS `Cittadinanza`, `R`.`LuogoNascita` AS `LuogoNascita`, `R`.`DataNascita` AS `DataNascita`, `R`.`TipoAlloggio` AS `TipoAlloggio`, `R`.`Residenza` AS `Residenza`, `R`.`Via` AS `Via`, `R`.`nMembri` AS `nMembri`, `R`.`Telefono` AS `Telefono`, `R`.`Mail` AS `Mail`, `P`.`PunteggioISEE` AS `PunteggioISEE`, `P`.`PunteggioPresenzaMinori` AS `PunteggioPresenzaMinori`, `P`.`PunteggioDisoccupazione` AS `PunteggioDisoccupazione`, `P`.`PunteggioInvalidi` AS `PunteggioInvalidi`, `P`.`PunteggioSituazioneDebitoria` AS `PunteggioSituazioneDebitoria`, `P`.`PunteggioBenefit` AS `PunteggioBenefit`, `P`.`PunteggioTotale` AS `PunteggioTotale`, `TR`.`CodiceTessera` AS `CodiceTessera`, date_format(`TR`.`DataOraRilascioTessera`,'%d/%m/%Y') AS `DataOraRilascioTessera`, date_format(`TR`.`DataOraScadenzaTessera`,'%d/%m/%Y') AS `DataOraScadenzaTessera`, date_format(`R`.`DataOraRitiroTessera`,'%d/%m/%Y') AS `DataOraRitiroTessera`, date_format(`R`.`DataOraStalloTessera`,'%d/%m/%Y') AS `DataOraStalloTessera` FROM (((`Richiedente` `R` left join `TesseraRilasciata` `TR` on(`R`.`Cod_Fiscale` = `TR`.`CodFamiglia`)) left join `Tessera` `T` on(`TR`.`CodiceTessera` = `T`.`Codice`)) join `Punteggio` `P` on(`R`.`Cod_Fiscale` = `P`.`CodFamiglia`)) ORDER BY `P`.`PunteggioTotale` DESC",
    'Graduatoria' => "SELECT `R`.`Cod_Fiscale` AS `Cod_Fiscale`, `R`.`Cognome` AS `Cognome`, `R`.`Nome` AS `Nome`, `R`.`nMembri` AS `nMembri`, `R`.`Telefono` AS `Telefono`, `R`.`Mail` AS `Mail`, `P`.`PunteggioISEE` AS `PunteggioISEE`, `P`.`PunteggioPresenzaMinori` AS `PunteggioPresenzaMinori`, `P`.`PunteggioDisoccupazione` AS `PunteggioDisoccupazione`, `P`.`PunteggioInvalidi` AS `PunteggioInvalidi`, `P`.`PunteggioSituazioneDebitoria` AS `PunteggioSituazioneDebitoria`, `P`.`PunteggioBenefit` AS `PunteggioBenefit`, `P`.`PunteggioTotale` AS `PunteggioTotale`, `TR`.`CodiceTessera` AS `CodiceTessera`, date_format(`TR`.`DataOraRilascioTessera`,'%d/%m/%Y') AS `DataOraRilascioTessera`, date_format(`TR`.`DataOraScadenzaTessera`,'%d/%m/%Y') AS `DataOraScadenzaTessera`, date_format(`R`.`DataOraRitiroTessera`,'%d/%m/%Y') AS `DataOraRitiroTessera`, date_format(`R`.`DataOraStalloTessera`,'%d/%m/%Y') AS `DataOraStalloTessera` FROM (((`Richiedente` `R` left join `TesseraRilasciata` `TR` on(`R`.`Cod_Fiscale` = `TR`.`CodFamiglia`)) left join `Tessera` `T` on(`TR`.`CodiceTessera` = `T`.`Codice`)) join `Punteggio` `P` on(`R`.`Cod_Fiscale` = `P`.`CodFamiglia`)) ORDER BY `P`.`PunteggioTotale` DESC",
    'InformazioniDispColl' => "SELECT `DispCollaborative`.`AmbitoFormativo` AS `AmbitoFormativo`, `DispCollaborative`.`AmbitoLavorativo` AS `AmbitoLavorativo`, `DispCollaborative`.`AmbitoSociale` AS `AmbitoSociale`, `DispCollaborative`.`CodFamiglia` AS `CodFamiglia` FROM `DispCollaborative`",
    'InformazioniMembri' => "SELECT `Membri`.`nMembro` AS `nMembro`, `Membri`.`NomeCognome` AS `NomeCognome`, `Membri`.`LuogoNascita` AS `LuogoNascita`, date_format(`Membri`.`DataNascita`,'%d/%m/%Y') AS `DataNascita`, `Membri`.`Parentela` AS `Parentela`, `Membri`.`Occupazione` AS `Occupazione`, `Membri`.`TitoloDiStudio` AS `TitoloDiStudio`, `Membri`.`Competenze` AS `Competenze`, `Membri`.`ConoscenzaLingua` AS `ConoscenzaLingua`, `Membri`.`Patente` AS `Patente`, `Membri`.`AttualeAtt` AS `AttualeAtt`, `Membri`.`Presso` AS `Presso`, `Membri`.`Termine` AS `Termine`, `Membri`.`SenzaLavoroDa` AS `SenzaLavoroDa`, `Membri`.`CodFamiglia` AS `CodFamiglia` FROM `Membri`",
    'InformazioniRichiedente' => "SELECT `R`.`Cod_Fiscale` AS `Cod_Fiscale`, `R`.`Cognome` AS `Cognome`, `R`.`Nome` AS `Nome`, `R`.`LuogoNascita` AS `LuogoNascita`, date_format(`R`.`DataNascita`,'%d/%m/%Y') AS `DataNascita`, `R`.`Cittadinanza` AS `Cittadinanza`, `R`.`InItaliaDallAnno` AS `InItaliaDallAnno`, `R`.`Residenza` AS `Residenza`, `R`.`Via` AS `Via`, `R`.`TipoAlloggio` AS `TipoAlloggio`, `R`.`DocumentoIdent` AS `DocumentoIdent`, `R`.`DocumentoImmig` AS `DocumentoImmig`, `R`.`Telefono` AS `Telefono`, `R`.`Mail` AS `Mail`, `R`.`ServiziSociali` AS `ServiziSociali`, `R`.`ComeHaConosciutoEmporio` AS `ComeHaConosciutoEmporio`, `R`.`nMembri` AS `nMembri`, `R`.`ISEE` AS `ISEE`, `TR`.`CodiceTessera` AS `CodiceTessera`, date_format(`TR`.`DataOraRilascioTessera`,'%d/%m/%Y') AS `DataOraRilascioTessera`, date_format(`TR`.`DataOraScadenzaTessera`,'%d/%m/%Y') AS `DataOraScadenzaTessera`, date_format(`R`.`DataOraRitiroTessera`,'%d/%m/%Y') AS `DataOraRitiroTessera`, date_format(`R`.`DataOraStalloTessera`,'%d/%m/%Y') AS `DataOraStalloTessera`, `P`.`PunteggioISEE` AS `PunteggioISEE`, `P`.`PunteggioPresenzaMinori` AS `PunteggioPresenzaMinori`, `P`.`PunteggioDisoccupazione` AS `PunteggioDisoccupazione`, `P`.`PunteggioInvalidi` AS `PunteggioInvalidi`, `P`.`PunteggioSituazioneDebitoria` AS `PunteggioSituazioneDebitoria`, `P`.`PunteggioBenefit` AS `PunteggioBenefit`, `P`.`PunteggioTotale` AS `PunteggioTotale` FROM (((`Richiedente` `R` left join `TesseraRilasciata` `TR` on(`R`.`Cod_Fiscale` = `TR`.`CodFamiglia`)) left join `Tessera` `T` on(`TR`.`CodiceTessera` = `T`.`Codice`)) join `Punteggio` `P` on(`R`.`Cod_Fiscale` = `P`.`CodFamiglia`)) ORDER BY `P`.`PunteggioTotale` DESC",
    'InformazioniSSS' => "SELECT `SituazioneSocioSanitaria`.`N` AS `N`, `SituazioneSocioSanitaria`.`Evento` AS `Evento`, `SituazioneSocioSanitaria`.`Anno` AS `Anno`, `SituazioneSocioSanitaria`.`DocAll` AS `DocAll`, `SituazioneSocioSanitaria`.`CodFamiglia` AS `CodFamiglia` FROM `SituazioneSocioSanitaria`",
    'Pass' => "SELECT `R`.`Cod_Fiscale` AS `Cod_Fiscale`, `R`.`Cognome` AS `Cognome`, `R`.`Nome` AS `Nome`, `R`.`nMembri` AS `nMembri`, `P`.`PunteggioISEE` AS `PunteggioISEE`, `P`.`PunteggioPresenzaMinori` AS `PunteggioPresenzaMinori`, `P`.`PunteggioDisoccupazione` AS `PunteggioDisoccupazione`, `P`.`PunteggioInvalidi` AS `PunteggioInvalidi`, `P`.`PunteggioSituazioneDebitoria` AS `PunteggioSituazioneDebitoria`, `P`.`PunteggioBenefit` AS `PunteggioBenefit`, `P`.`PunteggioTotale` AS `PunteggioTotale`, `TR`.`CodiceTessera` AS `CodiceTessera`, date_format(`TR`.`DataOraRilascioTessera`,'%d/%m/%Y') AS `DataOraRilascioTessera`, date_format(`TR`.`DataOraScadenzaTessera`,'%d/%m/%Y') AS `DataOraScadenzaTessera`, date_format(`R`.`DataOraRitiroTessera`,'%d/%m/%Y') AS `DataOraRitiroTessera`, date_format(`R`.`DataOraStalloTessera`,'%d/%m/%Y') AS `DataOraStalloTessera` FROM (((`Richiedente` `R` left join `TesseraRilasciata` `TR` on(`R`.`Cod_Fiscale` = `TR`.`CodFamiglia`)) left join `Tessera` `T` on(`TR`.`CodiceTessera` = `T`.`Codice`)) join `Punteggio` `P` on(`R`.`Cod_Fiscale` = `P`.`CodFamiglia`)) ORDER BY `P`.`PunteggioTotale` DESC",
    'StoricoTes' => "SELECT `ST`.`OrdineCronologico` AS `OrdineCronologico`, `ST`.`CodiceTessera` AS `CodiceTessera`, `ST`.`CodFamiglia` AS `CodFamiglia`, `R`.`Nome` AS `Nome`, `R`.`Cognome` AS `Cognome`, date_format(`ST`.`DataRilascio`,'%d/%m/%Y') AS `DataRilascio`, date_format(`ST`.`DataRitiro`,'%d/%m/%Y') AS `DataRitiro` FROM (`StoricoTessere` `ST` join `Richiedente` `R` on(`ST`.`CodFamiglia` = `R`.`Cod_Fiscale`)) ORDER BY `ST`.`OrdineCronologico` DESC",
];

function from(string $view): string
{
    if (!isset(VIEWS[$view])) {
        throw new InvalidArgumentException("Unknown view $view");
    }
    return '(' . VIEWS[$view] . ") AS `$view`";
}
